INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-03-1-section-2-sentence-3-1','cet4-2023-03-1',102,0,'That''s what happened on the German island of Langeoog this week.','cet4-2023-03-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-03-1-section-2-sentence-4-1','cet4-2023-03-1',103,0,'Lying just off the North Sea coast, it found itself struck by an invasion of colored plastic eggs-much to the delight of local children, because the eggs contained toys.','cet4-2023-03-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-03-1-section-2-sentence-5-1','cet4-2023-03-1',104,0,'Police suspect the eggs came from a freighter that lost part of its cargo during an unusually intense storm, the worst to hit Germany''s northeastern coast since 2006.','cet4-2023-03-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-03-1-section-2-sentence-6-1','cet4-2023-03-1',105,0,'At any rate, what was lost has now been found by many of the community''s littlest residents.','cet4-2023-03-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-03-1-section-2-sentence-7-1','cet4-2023-03-1',106,0,'"The surprise eggs have found their way to freedom," said Mayor Uwe Garrels.','cet4-2023-03-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-03-1-section-2-sentence-7-2','cet4-2023-03-1',106,1,'However, the joy of the moment wore off soon.','cet4-2023-03-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-03-1-section-2-sentence-8-1','cet4-2023-03-1',107,0,'"At first I thought this was a wonder, because everything was so colorful , but then we realized that this is a huge mess in the end," said the mayor.','cet4-2023-03-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-03-1-section-2-sentence-8-2','cet4-2023-03-1',107,1,'He also noted the plastic bags and other materials that have washed ashore on the island can cause serious problems for wildlife .','cet4-2023-03-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
