INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-03-3-section-2-sentence-8-1','cet4-2023-03-3',107,0,'"At first I thought this was a wonder, because everything was so colorful , but then we realized that this is a huge mess in the end," said the mayor.','cet4-2023-03-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
