INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-06-1-section-4-sentence-5-2','cet4-2023-06-1',304,1,'We must change the way we think: living well does not need to mean having more private spaces; instead, it could mean having more public spaces.','cet4-2023-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
