INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-12-3-section-3-sentence-12-5','cet4-2023-12-3',211,4,'This is precisely why parents still need to set firm boundaries around it, as with any other distraction.','cet4-2023-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
