INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-12-3-section-3-sentence-13-4','cet4-2023-12-3',212,3,'Parents who stare non-stop at their phones and don''t read books are likely to breed kids who will do the same.','cet4-2023-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
