INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-2-sentence-1-1','cet4-2025-12-3',100,0,'Earth Day is an annual celebration that honors the achievements of the environmental movement and raises awareness of the need to protect Earth''s natural resources for future generations.','cet4-2025-12-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-2-sentence-1-2','cet4-2025-12-3',100,1,'Earth Day is celebrated on April 22 in the United States and on either April 22 or the day the spring equinox (春分) occurs throughout the rest of the world.','cet4-2025-12-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-2-sentence-2-1','cet4-2025-12-3',101,0,'Environmental activism during the 1960s inspired Wisconsin Senator Gaylord Nelson to create a national celebration uniting the environmental movement.','cet4-2025-12-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-2-sentence-2-2','cet4-2025-12-3',101,1,'With the help of Denis Hayes, a graduate student at Harvard University, Nelson organized the first Earth Day on April 22,1970, educating participants in the importance of environmental protection.','cet4-2025-12-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-2-sentence-2-3','cet4-2025-12-3',101,2,'Attended by.20 million people across the United States, the event strengthened support for legislation such as the Clean Air Act and the Endangered Species Act.','cet4-2025-12-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-2-sentence-3-1','cet4-2025-12-3',102,0,'In 1990, Hayes organized a global Earth Day, with more than 200 million participants in 140 countries.','cet4-2025-12-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-2-sentence-3-2','cet4-2025-12-3',102,1,'Earth Day now brings together citizens and activists from around the world to raise awareness and take action regarding such environmental concerns as global warming and renewable energy.','cet4-2025-12-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-2-sentence-4-1','cet4-2025-12-3',103,0,'Today, the Earth Day Network, which rallies more than 20,000 partners and organizations in 190 countries, supports the Earth Day mission year-round.','cet4-2025-12-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-2-sentence-4-2','cet4-2025-12-3',103,1,'This mission is founded on the proposition that all people, regardless of race, gender, income, or geography, have a moral right to a healthy, sustainable environment.','cet4-2025-12-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-2-sentence-4-3','cet4-2025-12-3',103,2,'The Earth Day Network pursues this mission through education, public policy, and activism campaigns.','cet4-2025-12-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-12-3-section-3','cet4-2025-12-3',2,'matching','长篇阅读（36–45）· Looking for a job after 45','In this section, you are going to read a passage with ten statements attached to it. Each statement contains information given in one of the paragraphs. Identify the paragraph from which the information is derived. You may choose a paragraph more than once. Each paragraph is marked with a letter: Answer the questions by marking the corresponding letter on Answer Sheet 2.','["[A] Ageism and long-term unemployment are most damaging for those in the second half of their careers. Changing careers is hard. Getting back into work after you''ve been laid off is even harder. Those over 45 make up the bulk of the long-term unemployed, in America and elsewhere. Hiring managers admit they are reluctant to hire those over 40 or 45, arguing they probably won''t be a good \"fit,\" their experience won''t be relevant to the workplace, and they''ll be unable or unwilling to learn new skills.","[B] But the one thing that can really make a difference? More education and training. These are the results from a new study by Generation, a nonprofit founded by former McKinsey consultants. They''ve just published a global survey on midcareer employment, based on surveys of over 5,000 workers and managers in seven countries.","[C] “Older midcareer workers. make up the bulk of the long-term unemployed in many countries, \" Generation''s analysts write in their report. Those over 45 comprise over 40% of the long-term unemployed, for example. And if you''re out of work past the age of 45, there''s nearly a two in three chance you''ll be out of work for over a year, they find. “Midcareer individuals are finding it harder to get jobs,\" they write. \"People age 45+ face persistent and rising pressure in the global job market. They are unemployed for much longer than the average, and their age is indeed one of the greatest barriers to their finding a job.”","[D] A substantial part of this, they report, is “widespread ageism” on the part of hiring managers. Although such managers admit that post-45 hires turn out on average to be just as good as or better than younger workers, they still don''t want to hire them. \"Hiring managers have a strong perception bias against 45+ job candidates—they believe that members of this age group have poor skills and low adaptability,” Generation''s analysts report.","[E] The survey results are remarkable. Hiring managers are three times as likely to rate job applicants age 35-44 as a better \"fit\" than those over 45. They rate the post-45 job seekers lower on average on all three measures—even experience—than those ages 18 to 34. This is true even though nearly nine managers in 10 also said their post-45 workers were as good as or better than younger employees in the same jobs.","[F] Their biggest fears about hiring those over 45? Managers said they worry that older hires will be reluctant to try new technologies, and will be unable to learn new skills. Besides, the majority of hiring managers are under 45—and seem reluctant to hire people older than themselves.","[G] But here''s the good news. Older workers who''ve actively engaged in more education and training relevant to their jobs turn this pretty much on its head. Three-quarters of hiring managers said they''d be more likely to hire an over-45 who had relevant education, training or credentials (文凭). Among those over 45 who''d successfully switched careers,74% said training helped them get their new job.","[H] \"Midcareer switchers overwhelmingly say that training enabled them to shift to a new career path,\" the analysts write. And when they asked over-45 candidates about their attitudes, they found that “those who are excited by training are unemployed for less time, receive more job offers, and are more satisfied by the job offers they receive.”","[I] Hiring managers said training was three times more likely to get them to hire applicants over age 45 than, say, government subsidies (补贴). What training are we talking about? Obviously it depends on the job. And, yes, managers are most likely to be impressed by industry qualifications you get in school. These things cost money, and time. But these aren''t the only things helpful. Those who had successfully changed careers after 45 told Generation that education and training had been a big help—and that included in-person, on-the-job training,\" informal learning,\" and online courses—with or without certification.","[J] If they think we''re too old to learn new skills after we''re 45, just learning some new skills may have an effect on its own. There''s a downside to this. The people least interested in retraining are more likely to come from historically disadvantaged communities, more likely to have low incomes, and are more likely to have the least schooling after getting their high-school diploma or earlier. On average, post-45 job switchers with higher incomes participate in 2.5 training programs each. Those with lower incomes:0.9 programs on average.","[K] Many years ago, I wrote about a study which found that employers are much more likely to hire a college graduate who has some work experience in the industry than a college graduate who took the “right” degree. A bank is more likely to hire a literature graduate who spent their summers working in their local bank than a finance or economics graduate who spent their summers surfing or traveling around Italy. They''ve learned through long experience. The person who worked in the bank is more likely ready, willing and able to be part of the team and do the job from day 1.","[L] We can rail against “ageism” all we like. It gets us nowhere. And it''s easy to forget that employers, like everyone else, are under time pressure and are just trying to solve problems. Any and all “\"training,\" including inexpensive and informal training, is going to help resolve their worries about hiring someone over 45. And it has never been easier or cheaper to gain instruction in new skills, thanks to the internet. Online schools like Udemy and Lynda. com offer sweet deals at sign-up. And courses on YouTube are free.","[M] Bottom line? Yes, it really can be difficult getting a new job after age 45, let alone changing careers. One of the best things we can do to help ourselves is to go online and learn new, relevant skills. Sadly, the people who most need the help are least likely to take it—which raises a challenge for society as a whole. Not only do we not want to see lives go to waste, but we all benefit if more people are working and fewer are unemployed."]','["Ageism and long-term unemployment are most damaging for those in the second half of their careers. Changing careers is hard. Getting back into work after you''ve been laid off is even harder. Those over 45 make up the bulk of the long-term unemployed, in America and elsewhere. Hiring managers admit they are reluctant to hire those over 40 or 45, arguing they probably won''t be a good \"fit,\" their experience won''t be relevant to the workplace, and they''ll be unable or unwilling to learn new skills.","But the one thing that can really make a difference? More education and training. These are the results from a new study by Generation, a nonprofit founded by former McKinsey consultants. They''ve just published a global survey on midcareer employment, based on surveys of over 5,000 workers and managers in seven countries.","“Older midcareer workers. make up the bulk of the long-term unemployed in many countries, \" Generation''s analysts write in their report. Those over 45 comprise over 40% of the long-term unemployed, for example. And if you''re out of work past the age of 45, there''s nearly a two in three chance you''ll be out of work for over a year, they find. “Midcareer individuals are finding it harder to get jobs,\" they write. \"People age 45+ face persistent and rising pressure in the global job market. They are unemployed for much longer than the average, and their age is indeed one of the greatest barriers to their finding a job.”","A substantial part of this, they report, is “widespread ageism” on the part of hiring managers. Although such managers admit that post-45 hires turn out on average to be just as good as or better than younger workers, they still don''t want to hire them. \"Hiring managers have a strong perception bias against 45+ job candidates—they believe that members of this age group have poor skills and low adaptability,” Generation''s analysts report.","The survey results are remarkable. Hiring managers are three times as likely to rate job applicants age 35-44 as a better \"fit\" than those over 45. They rate the post-45 job seekers lower on average on all three measures—even experience—than those ages 18 to 34. This is true even though nearly nine managers in 10 also said their post-45 workers were as good as or better than younger employees in the same jobs.","Their biggest fears about hiring those over 45? Managers said they worry that older hires will be reluctant to try new technologies, and will be unable to learn new skills. Besides, the majority of hiring managers are under 45—and seem reluctant to hire people older than themselves.","But here''s the good news. Older workers who''ve actively engaged in more education and training relevant to their jobs turn this pretty much on its head. Three-quarters of hiring managers said they''d be more likely to hire an over-45 who had relevant education, training or credentials (文凭). Among those over 45 who''d successfully switched careers,74% said training helped them get their new job.","\"Midcareer switchers overwhelmingly say that training enabled them to shift to a new career path,\" the analysts write. And when they asked over-45 candidates about their attitudes, they found that “those who are excited by training are unemployed for less time, receive more job offers, and are more satisfied by the job offers they receive.”","Hiring managers said training was three times more likely to get them to hire applicants over age 45 than, say, government subsidies (补贴). What training are we talking about? Obviously it depends on the job. And, yes, managers are most likely to be impressed by industry qualifications you get in school. These things cost money, and time. But these aren''t the only things helpful. Those who had successfully changed careers after 45 told Generation that education and training had been a big help—and that included in-person, on-the-job training,\" informal learning,\" and online courses—with or without certification.","If they think we''re too old to learn new skills after we''re 45, just learning some new skills may have an effect on its own. There''s a downside to this. The people least interested in retraining are more likely to come from historically disadvantaged communities, more likely to have low incomes, and are more likely to have the least schooling after getting their high-school diploma or earlier. On average, post-45 job switchers with higher incomes participate in 2.5 training programs each. Those with lower incomes:0.9 programs on average.","Many years ago, I wrote about a study which found that employers are much more likely to hire a college graduate who has some work experience in the industry than a college graduate who took the “right” degree. A bank is more likely to hire a literature graduate who spent their summers working in their local bank than a finance or economics graduate who spent their summers surfing or traveling around Italy. They''ve learned through long experience. The person who worked in the bank is more likely ready, willing and able to be part of the team and do the job from day 1.","We can rail against “ageism” all we like. It gets us nowhere. And it''s easy to forget that employers, like everyone else, are under time pressure and are just trying to solve problems. Any and all “\"training,\" including inexpensive and informal training, is going to help resolve their worries about hiring someone over 45. And it has never been easier or cheaper to gain instruction in new skills, thanks to the internet. Online schools like Udemy and Lynda. com offer sweet deals at sign-up. And courses on YouTube are free.","Bottom line? Yes, it really can be difficult getting a new job after age 45, let alone changing careers. One of the best things we can do to help ourselves is to go online and learn new, relevant skills. Sadly, the people who most need the help are least likely to take it—which raises a challenge for society as a whole. Not only do we not want to see lives go to waste, but we all benefit if more people are working and fewer are unemployed."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-3-section-3-q-36','cet4-2025-12-3-section-3',0,'choice','36. Hiring managers believe unemployed workers over 45 lack good skills and are less adaptable.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','D','参考答案 D，依据原文整理。D 段说招聘经理对 45 岁以上申请者存在偏见，认为他们技能不足、适应性差。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-3-section-3-q-37','cet4-2025-12-3-section-3',1,'choice','37. Switching to a new career is difficult and getting reemployed after a layoff is even tougher.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','A','参考答案 A，依据原文整理。A 段开头指出转行困难，被裁员后重返工作岗位更加困难。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-3-section-3-q-38','cet4-2025-12-3-section-3',2,'choice','38. People from poor neighborhoods tend to have the least interest in retraining.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','J','参考答案 J，依据原文整理。J 段说最不愿接受再培训的人更多来自弱势社区，收入较低、教育经历较少。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-3-section-3-q-39','cet4-2025-12-3-section-3',3,'choice','39. Hiring managers who are not yet 45 years old seem unwilling to hire people their senior.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','F','参考答案 F，依据原文整理。F 段说大多数招聘经理未满 45 岁，似乎不愿招比自己年长的人。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-3-section-3-q-40','cet4-2025-12-3-section-3',4,'choice','40. Some analysts find age 45+ jobless workers are most likely to be unemployed for more than a year.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','C','参考答案 C，依据原文整理。C 段说 45 岁以上失业者约有三分之二可能失业超过一年。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-3-section-3-q-41','cet4-2025-12-3-section-3',5,'choice','41. People who had succeeded in career change after 45 told a nonprofit organization they owed a great deal to the education and training they had received.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','I','参考答案 I，依据原文整理。I 段介绍成功转行者告诉 Generation，教育和培训对他们帮助很大。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-3-section-3-q-42','cet4-2025-12-3-section-3',6,'choice','42. Older workers who actively pursue more education and training have a good chance of being hired.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','G','参考答案 G，依据原文整理。G 段说相关教育、培训或资格证书使招聘经理更愿意录用 45 岁以上的人。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-3-section-3-q-43','cet4-2025-12-3-section-3',7,'choice','43. A new study finds that more education and training helps midcareer individuals find a new job.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','B','参考答案 B，依据原文整理。B 段介绍新调查的结论：更多教育和培训能改善职业中期的就业机会。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-3-section-3-q-44','cet4-2025-12-3-section-3',8,'choice','44. Owing to the internet, it is now more convenient than ever to receive training in new skills.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','L','参考答案 L，依据原文整理。L 段说互联网让学习新技能更加容易、便宜，并列举在线课程。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-12-3-section-3-q-45','cet4-2025-12-3-section-3',9,'choice','45. People over 45 stimulated by training suffer shorter periods of unemployment, get more job offers and have greater satisfaction in them.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"},{"key":"M","text":"段落 M"}]','H','参考答案 H，依据原文整理。H 段指出对培训感兴趣的人失业时间更短，获得更多、也更满意的工作邀约。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-1-1','cet4-2025-12-3',200,0,'Ageism and long-term unemployment are most damaging for those in the second half of their careers.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-1-2','cet4-2025-12-3',200,1,'Changing careers is hard.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-1-3','cet4-2025-12-3',200,2,'Getting back into work after you''ve been laid off is even harder.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-1-4','cet4-2025-12-3',200,3,'Those over 45 make up the bulk of the long-term unemployed, in America and elsewhere.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-1-5','cet4-2025-12-3',200,4,'Hiring managers admit they are reluctant to hire those over 40 or 45, arguing they probably won''t be a good "fit," their experience won''t be relevant to the workplace, and they''ll be unable or unwilling to learn new skills.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-2-1','cet4-2025-12-3',201,0,'But the one thing that can really make a difference?','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-2-2','cet4-2025-12-3',201,1,'More education and training.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-2-3','cet4-2025-12-3',201,2,'These are the results from a new study by Generation, a nonprofit founded by former McKinsey consultants.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-2-4','cet4-2025-12-3',201,3,'They''ve just published a global survey on midcareer employment, based on surveys of over 5,000 workers and managers in seven countries.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-3-1','cet4-2025-12-3',202,0,'“Older midcareer workers. make up the bulk of the long-term unemployed in many countries, " Generation''s analysts write in their report.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-3-2','cet4-2025-12-3',202,1,'Those over 45 comprise over 40% of the long-term unemployed, for example.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-3-3','cet4-2025-12-3',202,2,'And if you''re out of work past the age of 45, there''s nearly a two in three chance you''ll be out of work for over a year, they find.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-3-4','cet4-2025-12-3',202,3,'“Midcareer individuals are finding it harder to get jobs," they write.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-3-5','cet4-2025-12-3',202,4,'"People age 45+ face persistent and rising pressure in the global job market.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-3-6','cet4-2025-12-3',202,5,'They are unemployed for much longer than the average, and their age is indeed one of the greatest barriers to their finding a job.”','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-4-1','cet4-2025-12-3',203,0,'A substantial part of this, they report, is “widespread ageism” on the part of hiring managers.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-4-2','cet4-2025-12-3',203,1,'Although such managers admit that post-45 hires turn out on average to be just as good as or better than younger workers, they still don''t want to hire them.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-4-3','cet4-2025-12-3',203,2,'"Hiring managers have a strong perception bias against 45+ job candidates—they believe that members of this age group have poor skills and low adaptability,” Generation''s analysts report.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-5-1','cet4-2025-12-3',204,0,'The survey results are remarkable.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-5-2','cet4-2025-12-3',204,1,'Hiring managers are three times as likely to rate job applicants age 35-44 as a better "fit" than those over 45.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-5-3','cet4-2025-12-3',204,2,'They rate the post-45 job seekers lower on average on all three measures—even experience—than those ages 18 to 34.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-5-4','cet4-2025-12-3',204,3,'This is true even though nearly nine managers in 10 also said their post-45 workers were as good as or better than younger employees in the same jobs.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-6-1','cet4-2025-12-3',205,0,'Their biggest fears about hiring those over 45?','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-6-2','cet4-2025-12-3',205,1,'Managers said they worry that older hires will be reluctant to try new technologies, and will be unable to learn new skills.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-6-3','cet4-2025-12-3',205,2,'Besides, the majority of hiring managers are under 45—and seem reluctant to hire people older than themselves.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-7-1','cet4-2025-12-3',206,0,'But here''s the good news.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-7-2','cet4-2025-12-3',206,1,'Older workers who''ve actively engaged in more education and training relevant to their jobs turn this pretty much on its head.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-7-3','cet4-2025-12-3',206,2,'Three-quarters of hiring managers said they''d be more likely to hire an over-45 who had relevant education, training or credentials (文凭).','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-7-4','cet4-2025-12-3',206,3,'Among those over 45 who''d successfully switched careers,74% said training helped them get their new job.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-8-1','cet4-2025-12-3',207,0,'"Midcareer switchers overwhelmingly say that training enabled them to shift to a new career path," the analysts write.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-8-2','cet4-2025-12-3',207,1,'And when they asked over-45 candidates about their attitudes, they found that “those who are excited by training are unemployed for less time, receive more job offers, and are more satisfied by the job offers they receive.”','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-9-1','cet4-2025-12-3',208,0,'Hiring managers said training was three times more likely to get them to hire applicants over age 45 than, say, government subsidies (补贴).','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
