INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-1-2','cet6-2025-06-3',200,1,'I’m sometimes secretly pleased when social plans are called off.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-1-3','cet6-2025-06-3',200,2,'I get restless a few hours into a hangout.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-1-4','cet6-2025-06-3',200,3,'I even once went on a free 10-day silent meditation (冥想) retreat—not for the meditation, but for the silence.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-2-1','cet6-2025-06-3',201,0,'So I can relate to author Anneli Rufus, who wrote in Party of One: The Loners’ Manifesto: “When parents on TV shows punished their kids by ordering them to go to their rooms, I was confused.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-2-2','cet6-2025-06-3',201,1,'I loved my room.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-2-3','cet6-2025-06-3',201,2,'Being there behind a locked door was a treat.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-2-4','cet6-2025-06-3',201,3,'To me a punishment was being ordered to play games with my cousin Louis.”','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-3-1','cet6-2025-06-3',202,0,'Unsocial tendencies like these are often far from ideal.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-3-2','cet6-2025-06-3',202,1,'Abundant research shows the harms of social isolation, considered a serious public health problem in countries that have rapidly ageing populations (though talk of a ‘loneliness epidemic’ may be exaggerated).','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-3-3','cet6-2025-06-3',202,2,'In the UK, the Royal College of General Practitioners says that loneliness has the same risk level for premature death as diabetes.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-3-4','cet6-2025-06-3',202,3,'Strong social connections are important for cognitive functioning, motor function and a smoothly running immune system.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-4-1','cet6-2025-06-3',203,0,'This is especially clear from cases of extreme social isolation.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-4-2','cet6-2025-06-3',203,1,'Examples of people kept in captivity, children kept isolated in abusive orphanages, and prisoners kept in solitary confinement all show how prolonged solitude can lead to hallucinations (幻觉) and other forms of mental instability.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-5-1','cet6-2025-06-3',204,0,'But these are severe and involuntary cases of aloneness.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-5-2','cet6-2025-06-3',204,1,'For those of us who just prefer plenty of alone time, emerging research suggests some good news: there are upsides to being alone—for both our work lives and our emotional well-being.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-6-1','cet6-2025-06-3',205,0,'Solitude is a time for reflection, for thinking about things more deeply.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-6-2','cet6-2025-06-3',205,1,'In a world increasingly focused on speed and competitiveness, solitude is precious and something to be treasured.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-6-3','cet6-2025-06-3',205,2,'And there are benefits in learning to love your solitude.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-7-1','cet6-2025-06-3',206,0,'One key benefit of solitude is improved creativity.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-7-2','cet6-2025-06-3',206,1,'Gregory Feist, who focuses on the psychology of creativity at California’s San Jose State University, has defined creativity as thinking or activity with two key elements: originality and usefulness.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-7-3','cet6-2025-06-3',206,2,'He has found that personality traits commonly associated with creativity are openness (receptiveness to new thoughts and experiences), self-confidence, and autonomy—which may include“a lack of concern for social norms”and“a preference for being alone”.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-7-4','cet6-2025-06-3',206,3,'In fact, Feist’s research on both artists and scientists shows that one of the most prominent features of creative folks is their lesser interest in socialising.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-8-1','cet6-2025-06-3',207,0,'One reason for this is that such people are likely to spend sustained time alone working on their craft.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-8-2','cet6-2025-06-3',207,1,'Plus, Feist says, many artists “ are trying to make sense of their internal world and a lot of internal personal experiences that they’re trying to give expression and meaning to through their art. ” Solitude allows for the reflection and observation necessary for that creative process.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-9-1','cet6-2025-06-3',208,0,'A recent justification of these ideas came from University at Buffalo psychologist Julie Bowker, who researches social withdrawal.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-9-2','cet6-2025-06-3',208,1,'Social withdrawal is usually categorised into three types: shyness caused by fear or anxiety; avoidance, from a dislike of socialising; and unsociability, from a preference for solitude.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-9-3','cet6-2025-06-3',208,2,'A paper by Bowker and her colleagues was the first to s how that a type of social withdrawal could have a positive effect—they found that creativity was linked specifically to unsociability.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-9-4','cet6-2025-06-3',208,3,'They also found that unsociability had no correlation with aggression (shyness and avoidance did).','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-9-5','cet6-2025-06-3',208,4,'This was significant because while previous research had suggested that unsociability might be harmless, Bowker and colleagues’ paper showed that it could actually be beneficial.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-9-6','cet6-2025-06-3',208,5,'Unsociable people are likely to be “having just enough interaction,” Bowker says.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-9-7','cet6-2025-06-3',208,6,'“They have a preference for being alone, but they also don’ t mind being with others.”','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-10-1','cet6-2025-06-3',209,0,'Still, it turns out that solitude is important for more than creativity.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-10-2','cet6-2025-06-3',209,1,'It’s commonly believed that leaders need to be sociable.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-10-3','cet6-2025-06-3',209,2,'But this depends, among other things, on the personalities of their employees.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-10-4','cet6-2025-06-3',209,3,'One 2011 study showed that in branches of a pizza chain where employees were more passive, outgoing bosses were associated with higher profits.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-10-5','cet6-2025-06-3',209,4,'But in branches where employees were more active, introverted ( 内向的) leaders were more effective.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-10-6','cet6-2025-06-3',209,5,'One reason for this is that introverted people are less likely to feel threatened by strong personalities and suggestions.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-10-7','cet6-2025-06-3',209,6,'They’re also more likely to listen.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-11-1','cet6-2025-06-3',210,0,'Since ancient times, meanwhile, people have been aware of a link between isolation and mental focus.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-11-2','cet6-2025-06-3',210,1,'After all, cultures with traditions of religious hermits ( 隐士) believe that solitude is important for enlightenment.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-11-3','cet6-2025-06-3',210,2,'Recent research has given us a better understanding of why.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-11-4','cet6-2025-06-3',210,3,'One benefit of unsociability is the brain’s state of active mental rest, which goes hand-in-hand with the stillness of being alone.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-11-5','cet6-2025-06-3',210,4,'When another person is present, your brain can’t help but pay some attention.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-11-6','cet6-2025-06-3',210,5,'This can be a positive distraction.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-11-7','cet6-2025-06-3',210,6,'But it’s still a distraction.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-12-1','cet6-2025-06-3',211,0,'Daydreaming in the absence of such distractions activates the brain’ s default-mode network.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-12-2','cet6-2025-06-3',211,1,'Among other functions, this network helps to consolidate memory and understand others’ emotions.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-12-3','cet6-2025-06-3',211,2,'Giving free rein to a wandering mind not only helps with focus in the long term but strengthens your sense of both yourself and others.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-12-4','cet6-2025-06-3',211,3,'Paradoxically, therefore, periods of solitude actually help when it comes time to socialise once more.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-12-5','cet6-2025-06-3',211,4,'And the occasional absence of focus ultimately helps concentration in the long run.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-13-1','cet6-2025-06-3',212,0,'A more recent advocate of thoughtful and productive solitude is Susan Cain, author of Quiet: The Power of Introverts in a World That Can’t Stop Talking and founder of Quiet Revolution, a company that promotes quiet and introvert-friendly workplaces.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-13-2','cet6-2025-06-3',212,1,'“These days, we tend to believe that creativity emerges from a decidedly unreserved socialising process, but in fact it requires sustained attention and deep focus,” she says.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-13-3','cet6-2025-06-3',212,2,'“Also, humans are such absorbent social beings that when we surround ourselves with others, we automatically take in their opinions and aesthetics.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-13-4','cet6-2025-06-3',212,3,'To truly chart our own path or vision, we have to be willing to isolate ourselves, at least for some period of time.”','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-14-1','cet6-2025-06-3',213,0,'Still, the line between useful solitude and dangerous isolation can be blurry.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-14-2','cet6-2025-06-3',213,1,'“Almost anything can be adaptive and maladaptive, depending on how extreme they get, ” Feist says.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-14-3','cet6-2025-06-3',213,2,'A disorder has to do with dysfunction.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-14-4','cet6-2025-06-3',213,3,'If someone stops caring about people and cuts off all contact, this could point to an irrational neglect of social relations.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-14-5','cet6-2025-06-3',213,4,'But creative unsociability is a far cry from this.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-14-6','cet6-2025-06-3',213,5,'In fact, Feist says, “there’s a real danger with people who are never alone.”','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-14-7','cet6-2025-06-3',213,6,'It’s hard to examine one’ s own thoughts, feelings and motives, to be self-aware, and fully relaxed unless you have occasional solitude.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-14-8','cet6-2025-06-3',213,7,'In addition, introverts tend to have fewer but stronger friendships — which has been linked to greater happiness.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-15-1','cet6-2025-06-3',214,0,'As with many things, quality reigns over quantity.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-15-2','cet6-2025-06-3',214,1,'Nurturing a few solid relationships without feeling the need to constantly populate your life with endless chatting ultimately may be better for you.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-16-1','cet6-2025-06-3',215,0,'Thus, if your personality tends toward unsociability, you shouldn ’t feel the need to change.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-16-2','cet6-2025-06-3',215,1,'Of course, that comes with qualifications.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-06-3-section-3-sentence-16-3','cet6-2025-06-3',215,2,'But as long as you have regular social contact, you are choosing solitude rather than being forced into it, you have at least a few good friends and your solitude is good for your well-being or productivity, there’s no point agonising over how to fit a square personality into a round hole.','cet6-2025-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet6-2025-06-3-section-4','cet6-2025-06-3',3,'reading','仔细阅读 · Passage One（46–50）','Directions: There are 2 passages in this section. Each passage is followed by some questions or unfinished statements. For each of them there are four choices marked A), B), C) and D). You should decide on the best choice and mark the corresponding letter on Answer Sheet 2 with a single line through the centre.','["Simulators are most often utilized within industries such as nuclear power, aviation and surgery where failure results in disastrous consequences. To maximize the value from a simulation learning experience, participants should immediately and directly apply their learning to a specific intervention within their organization.","Most organizations aspire to deploy significant change programs, only to find them nearly impossible to implement. That is largely because successful change requires more than a vision, it requires a workforce that not only doesn’t resist change, but embraces it.","To achieve success, an organization must build a transformation program that will allow change to be rapidly pulled across its departments and throughout its layers. Regardless of the level of senior management commitment, unless key thought leaders at all levels embrace the change, the initiative will wither and die. To create this kind of widespread passion, learning leaders must expose the workforce to what could be, which will enable them to rethink their mental models, enable them to break free from their deep-rooted paradigms and embrace the opportunity to learn.","Allowing participants to enter a simulated environment provides them with the opportunity to experience alternative realities which can prompt them to rethink their current beliefs.","Behavioral change is not easy for most adults. Lectures, training programs and workshops can explain the intellectual elements of transformation, but they are seldom effective at getting to the behavioral aspects that lie at the heart of a significant change initiative. Further, under normal working conditions, managers rarely see the full effect of their employee development efforts. As such, an intervention like a simulation can provide the stimulus for change.","An effective simulation can be better than experience as a learning tool because it accelerates time, compresses space, and unlike reality, is specifically designed to maximize participant learning. Simulations provide an immersive learning experience where skills, processes and knowledge all can be highlighted in a way reality cannot. The ability to explore, experiment and repeatedly apply new knowledge in unlimited, risk-free models is what makes simulation one of the most productive forms of learning.","Well-designed simulations can enable individuals and groups to develop a deep level of understanding about how their decisions and intuitive responses to business stimuli affect their fellow participants and the organization as a whole. To reap the benefits, however, simulations must feel like reality. At the end of the successful simulation, participants must declare “this is us.” If they don’t, they will view the experience as a game, which can be difficult to apply on the job, or worse, irrelevant to everyday work tasks. To maximize benefits from simulation, participants should immediately apply the learning from the experience to forge a smooth link between learning and doing."]','["Simulators are most often utilized within industries such as nuclear power, aviation and surgery where failure results in disastrous consequences. To maximize the value from a simulation learning experience, participants should immediately and directly apply their learning to a specific intervention within their organization.","Most organizations aspire to deploy significant change programs, only to find them nearly impossible to implement. That is largely because successful change requires more than a vision, it requires a workforce that not only doesn’t resist change, but embraces it.","To achieve success, an organization must build a transformation program that will allow change to be rapidly pulled across its departments and throughout its layers. Regardless of the level of senior management commitment, unless key thought leaders at all levels embrace the change, the initiative will wither and die. To create this kind of widespread passion, learning leaders must expose the workforce to what could be, which will enable them to rethink their mental models, enable them to break free from their deep-rooted paradigms and embrace the opportunity to learn.","Allowing participants to enter a simulated environment provides them with the opportunity to experience alternative realities which can prompt them to rethink their current beliefs.","Behavioral change is not easy for most adults. Lectures, training programs and workshops can explain the intellectual elements of transformation, but they are seldom effective at getting to the behavioral aspects that lie at the heart of a significant change initiative. Further, under normal working conditions, managers rarely see the full effect of their employee development efforts. As such, an intervention like a simulation can provide the stimulus for change.","An effective simulation can be better than experience as a learning tool because it accelerates time, compresses space, and unlike reality, is specifically designed to maximize participant learning. Simulations provide an immersive learning experience where skills, processes and knowledge all can be highlighted in a way reality cannot. The ability to explore, experiment and repeatedly apply new knowledge in unlimited, risk-free models is what makes simulation one of the most productive forms of learning.","Well-designed simulations can enable individuals and groups to develop a deep level of understanding about how their decisions and intuitive responses to business stimuli affect their fellow participants and the organization as a whole. To reap the benefits, however, simulations must feel like reality. At the end of the successful simulation, participants must declare “this is us.” If they don’t, they will view the experience as a game, which can be difficult to apply on the job, or worse, irrelevant to everyday work tasks. To maximize benefits from simulation, participants should immediately apply the learning from the experience to forge a smooth link between learning and doing."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet6-2025-06-3-section-4-q-46','cet6-2025-06-3-section-4',0,'choice','46. What do we learn about successful changes in organizations?','[{"key":"A","text":"They can be immediately implemented with great ease."},{"key":"B","text":"They are usually led by organization leaders of vision."},{"key":"C","text":"They call for enthusiastic support from the workforce."},{"key":"D","text":"They often result from simulation learning experiences."}]','C','参考答案 C，依据原文整理，非官方答案。第 2 段原文依据：That is largely because successful change requires more than a vision, it requires a workforce that not only doesn’t resist change, but embraces it. 对应选项：They call for enthusiastic support from the workforce.',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet6-2025-06-3-section-4-q-47','cet6-2025-06-3-section-4',1,'choice','47. What should learning leaders do to arouse learners’ passion for change?','[{"key":"A","text":"Allow them to see what could possibly be achieved."},{"key":"B","text":"Help them break free from their old paradigms."},{"key":"C","text":"Encourage them to rethink their thought models."},{"key":"D","text":"Stimulate them to embrace fresh opportunities."}]','A','参考答案 A，依据原文整理，非官方答案。第 3 段原文依据：To create this kind of widespread passion, learning leaders must expose the workforce to what could be, which will enable them to rethink their mental models, enable them to break free from their deep-rooted paradigms and embrace the opportunity to learn. 对应选项：Allow them to see what could possibly be achieved.',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet6-2025-06-3-section-4-q-48','cet6-2025-06-3-section-4',2,'choice','48. What does the passage say about lectures, training programs and workshops?','[{"key":"A","text":"They are generally incapable of changing workers’ behaviors on the job."},{"key":"B","text":"They are interventions different from simulations in creating stimuli for change."},{"key":"C","text":"They aim at transforming the behaviors of t he workers in an organization."},{"key":"D","text":"They help managers achieve the full effect of employee development efforts."}]','A','参考答案 A，依据原文整理，非官方答案。第 5 段原文依据：Lectures, training programs and workshops can explain the intellectual elements of transformation, but they are seldom effective at getting to the behavioral aspects that lie at the heart of a significant change initiative. 对应选项：They are generally incapable of changing workers’ behaviors on the job.',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet6-2025-06-3-section-4-q-49','cet6-2025-06-3-section-4',3,'choice','49. What makes simulation one of the most fruitful forms of learning?','[{"key":"A","text":"Its capability of saving time by accelerating the immersive learning experience."},{"key":"B","text":"Its potential for learners to examine their skills, knowledge and learning process."},{"key":"C","text":"Its capability of providing all participants with a practical learning experience."},{"key":"D","text":"Its potential for learners to explore, experiment and practice without any risk."}]','D','参考答案 D，依据原文整理，非官方答案。第 6 段原文依据：The ability to explore, experiment and repeatedly apply new knowledge in unlimited, risk-free models is what makes simulation one of the most productive forms of learning. 对应选项：Its potential for learners to explore, experiment and practice without any risk.',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet6-2025-06-3-section-4-q-50','cet6-2025-06-3-section-4',4,'choice','50. What should participants do in a simulation to reap the greatest benefits possible?','[{"key":"A","text":"Take the experience as a mere game."},{"key":"B","text":"Apply promptly what they learn to their jobs."},{"key":"C","text":"Develop a deep level of understanding."},{"key":"D","text":"Strive to connect closely with their leaders."}]','B','参考答案 B，依据原文整理，非官方答案。第 7 段原文依据：At the end of the successful simulation, participants must declare “this is us.” If they don’t, they will view the experience as a game, which can be difficult to apply on the job, or worse, irrelevant to everyday work tasks. 对应选项：Apply promptly what they learn to their jobs.',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
