INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-12-1-section-2-sentence-1-1','cet6-2025-12-1',100,0,'By now, it is generally accepted that regular exercise comes with an assortment of health benefits for people who maintain the habit over time.','cet6-2025-12-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
