INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet6-2025-12-2-section-1','cet6-2025-12-2',0,'writing','写作','Part I · Writing · 30 minutes','[]','["For this part, you are allowed 30 minutes to write an essay that begins with the sentence“While striving for the Chinese Dream, young people enjoy more opportunities to realize their self-worth. \"You can make comments, cite examples or use yourpersonal experiences to develop vour essay. You should write at least 150 words but no more than 200words. You should copy the sentence given in quotes at the beginning of your essay."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
