INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-12-2-section-5-sentence-6-4','cet6-2025-12-2',405,3,'I have my own plan for handling this, but I really appreciate your perspective and will take it into consideration.','cet6-2025-12-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
