INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet6-2025-12-3-section-1','cet6-2025-12-3',0,'writing','写作','Part I · Writing · 30 minutes','[]','["For this part, you are allowed 30 minutes to write an essay that begins with the sentence\"It is believed that teachers can exert a profound influence on their students''academic pursuit and personal development.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet6-2025-12-3-section-1-q-1','cet6-2025-12-3-section-1',0,'text','For this part, you are allowed 30 minutes to write an essay that begins with the sentence"It is believed that teachers can exert a profound influence on their students''academic pursuit and personal development.” You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.','[]',NULL,'PDF 未提供范文；作答保留供自行核对。',10) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
