INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-12-3-section-3-sentence-17-4','cet6-2025-12-3',216,3,'Steady Yellow Arrows maintain the normal yellow light caution in three-light signals, meaning to stop or prepare to stop.','cet6-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-12-3-section-3-sentence-17-5','cet6-2025-12-3',216,4,'In a four-signal system that has a flashing yellow arrow, the steady yellow arrow is a signal that the yield period is ending.','cet6-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
