INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2025-12-3-section-3-sentence-18-2','cet6-2025-12-3',217,1,'Green means it''s safe to proceed (though you should still exercise caution).','cet6-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
