INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet6-2026-06-1-section-1','cet6-2026-06-1',0,'writing','写作','Part I · Writing · 30 minutes','[]','["For this part, you are allowed 30 minutes to write an essay that begins with the sentence \"With the trend of Urbanization, it is vitally important for city residents to develop a stronger love for Nature. \" You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
