INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2026-06-1-section-4-sentence-4-7','cet6-2026-06-1',303,6,'The failure to protect children from data harvesting and targeted advertising thus far is as shocking as the lack of concern shown by the companies themselves with regard to children''s psychological health.','cet6-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2026-06-1-section-4-sentence-5-1','cet6-2026-06-1',304,0,'Of course, social media companies are not the source of all our ills, and can offer a too-easy target for politicians keen to divert attention from inadequately resourced schools and health services.','cet6-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2026-06-1-section-4-sentence-5-2','cet6-2026-06-1',304,1,'There are other reasons for the rising incidence of depression in young people, with increasing pressure to succeed in education and in life more broadly-to be famous, beautiful, rich -often cited as a source of unhappiness or anxiety which can, if aggravated by other factors, and not managed, tip into ill health.','cet6-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
