INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2026-06-2-section-5-sentence-8-1','cet6-2026-06-2',407,0,'I don''t think the U.S. government should regulate social media and teen smartphone use, but it is a vital topic for parents to understand and take seriously.','cet6-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2026-06-2-section-5-sentence-8-2','cet6-2026-06-2',407,1,'Unfortunately, now, parents don''t just have to worry about real-world dangers, but all the ones sneaking online and the effects they have on teenagers and their mental health.','cet6-2026-06-2-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet6-2026-06-2-section-6','cet6-2026-06-2',5,'translation','翻译 · 汉译英','Directions: For this part, you are allowed 30 minutes to translate a passage from Chinese into English. You should write your answer on Answer Sheet 2.','["电子商务的蓬勃发展正在深刻改变中国农村的面貌。随着互联网和物流网络快速向农村延伸，越来越多的农村居民通过电子商务平台将农产品直接销售给城市消费者。近年来，直播带货（live-streaming commerce）使城市消费者能够与卖家实时互动，已成为促进农村发展的一种新方式。电子商务打破了城乡之间的信息壁垒，拓宽了农产品销售渠道，帮助农村居民增收致富。数字经济与乡村振兴的深度融合，正在为中国农村发展注入前所未有的活力。"]','[]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet6-2026-06-2-section-6-q-1','cet6-2026-06-2-section-6',0,'text','将上面的中文段落译成英文。','[]',NULL,'PDF 未提供参考译文；作答保留供自行核对。',10) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO papers (id,exam_level,year,month,set_no,variant,title,is_demo,status,content_state,source_url,content_kind,description,reference_paper_id) VALUES ('cet6-2026-06-3','CET6',2026,6,3,'第3套','2026年6月大学英语六级（第3套）',FALSE,'published','local',NULL,'imported','按用户提供的试卷 PDF 导入全部非听力部分，保留写作要求、选词填空、长篇阅读、两篇仔细阅读及汉译英。PDF 未附答案，客观题参考答案依据原文整理，并非官方答案；做题保留空格，精读按参考答案补全。',NULL) ON CONFLICT (id) DO UPDATE SET exam_level=EXCLUDED.exam_level,year=EXCLUDED.year,month=EXCLUDED.month,set_no=EXCLUDED.set_no,variant=EXCLUDED.variant,title=EXCLUDED.title,is_demo=EXCLUDED.is_demo,status=EXCLUDED.status,content_state=EXCLUDED.content_state,source_url=EXCLUDED.source_url,content_kind=EXCLUDED.content_kind,description=EXCLUDED.description,reference_paper_id=EXCLUDED.reference_paper_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet6-2026-06-3-section-1','cet6-2026-06-3',0,'writing','写作','Part I · Writing · 30 minutes','[]','["For this part, you are allowed 30 minutes to write an essay that begins with the sentence \"Faced with growing globalization, students realize that a deep understanding of traditional Chinese culture helps cultivate cultural confidence. \" You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet6-2026-06-3-section-1-q-1','cet6-2026-06-3-section-1',0,'text','For this part, you are allowed 30 minutes to write an essay that begins with the sentence "Faced with growing globalization, students realize that a deep understanding of traditional Chinese culture helps cultivate cultural confidence. " You can make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200 words. You should copy the sentence given in quotes at the beginning of your essay.','[]',NULL,'PDF 未提供范文；作答保留供自行核对。',10) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
