INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet6-2026-06-3-section-3-sentence-12-3','cet6-2026-06-3',211,2,'She enjoyed them all, but best, in her view, is Money Match Cafe, a board game where she must work out the value of different denominations (面额) of coin in her imaginary restaurant, her "customers" being her stuffed toys.','cet6-2026-06-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
