INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet6-2026-06-3-section-6','cet6-2026-06-3',5,'translation','翻译 · 汉译英','Directions: For this part, you are allowed 30 minutes to translate a passage from Chinese into English. You should write your answer on Answer Sheet 2.','["近年来，中国无人机（drone）产业蓬勃发展，出口量跃升为全球第一。中国的无人机以出色的稳定性、高清（high-definition）拍摄能力和便捷的操作，受到全球消费者的喜爱，在民用领域得到广泛应用。无人机已被国家纳入战略性新兴产业，逐步成为能满足多种场景需求的智能助手。在农村，无人机可精准识别农作物病虫害，高效喷洒农药。在城市，无人机可快速运送生鲜食品。在不久的将来，无人机能够在更多领域实现其独特价值，为经济社会发展注入新动能。"]','[]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet6-2026-06-3-section-6-q-1','cet6-2026-06-3-section-6',0,'text','将上面的中文段落译成英文。','[]',NULL,'PDF 未提供参考译文；作答保留供自行核对。',10) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO papers (id,exam_level,year,month,set_no,variant,title,is_demo,status,content_state,source_url,content_kind,description,reference_paper_id) VALUES ('neep-2024-12-english-1','NEEP',2024,12,1,'英语一','2024年考研英语一',FALSE,'published','local',NULL,'imported','按用户提供的2024年全国硕士研究生招生考试英语（一）PDF 导入全部内容，含完形填空、四篇阅读、新题型、英译汉、小作文及大作文原图。年份采用卷面考试年度。PDF 未附答案，客观题参考答案依据原文整理，并非官方答案；翻译和写作保留为主观题。',NULL) ON CONFLICT (id) DO UPDATE SET exam_level=EXCLUDED.exam_level,year=EXCLUDED.year,month=EXCLUDED.month,set_no=EXCLUDED.set_no,variant=EXCLUDED.variant,title=EXCLUDED.title,is_demo=EXCLUDED.is_demo,status=EXCLUDED.status,content_state=EXCLUDED.content_state,source_url=EXCLUDED.source_url,content_kind=EXCLUDED.content_kind,description=EXCLUDED.description,reference_paper_id=EXCLUDED.reference_paper_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('neep-2024-12-english-1-section-1','neep-2024-12-english-1',0,'cloze','完形填空','Section I · Use of English. Read the following text.Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET.(10 points)','["There’s nothing more welcoming than a door opening for you. ____(1)____ the need to be touched to open or close, automatic doors are essential in ____(2)____ disabled access to buildings and helping provide general ____(3)____ to commercial buildings.","Self-sliding doors began to emerge as a commercial product in 1960 after being invented six years ____(4)____ by Americans Dee Horton and Lew Hewitt. They ____(5)____ as a novelty feature, but as their use has grown, their ____(6)____ have extended within our technologically advanced world. Particularly ____(7)____ in busy locations or during times of emergency, the doors ____(8)____ crowd management by reducing the obstacles put in peoples’ way.","____(9)____ making access both in and out of buildings easier for people, the difference in the way many of these doors open helps reduce the total area ____(10)____ by them. Automatic doors often open to the side, with the panels sliding across one another. Replacing swing doors, these ____(11)____ smaller buildings to maximise the usable space inside without having to ____(12)____ the way for a large, sticking-out door. There are many different types of automatic door, with each ____(13)____ specific signals to tell them when to open. ____(14)____ these methods differ, the main ____(15)____ remain the same.","Each automatic door system ____(16)____ the light, sound, weight or movement in their vicinity as a signal to open. Sensor types are chosen to ____(17)____ the different environments they are needed in. ____(18)____ , a busy street might not ____(19)____ a motion-sensored door, as it would constantly be opening for passers-by. A pressure-sensitive mat would be more ____(20)____ to limit the surveyed area."]','["There’s nothing more welcoming than a door opening for you. Without the need to be touched to open or close, automatic doors are essential in improving disabled access to buildings and helping provide general convenience to commercial buildings.","Self-sliding doors began to emerge as a commercial product in 1960 after being invented six years previously by Americans Dee Horton and Lew Hewitt. They started out as a novelty feature, but as their use has grown, their benefits have extended within our technologically advanced world. Particularly useful in busy locations or during times of emergency, the doors act as crowd management by reducing the obstacles put in peoples’ way.","As well as making access both in and out of buildings easier for people, the difference in the way many of these doors open helps reduce the total area occupied by them. Automatic doors often open to the side, with the panels sliding across one another. Replacing swing doors, these allow smaller buildings to maximise the usable space inside without having to clear the way for a large, sticking-out door. There are many different types of automatic door, with each relying on specific signals to tell them when to open. Although these methods differ, the main principles remain the same.","Each automatic door system analyses the light, sound, weight or movement in their vicinity as a signal to open. Sensor types are chosen to complement the different environments they are needed in. For example , a busy street might not suit a motion-sensored door, as it would constantly be opening for passers-by. A pressure-sensitive mat would be more appropriate to limit the surveyed area."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
