INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('neep-2024-12-english-1-section-1-sentence-1-1','neep-2024-12-english-1',0,0,'There’s nothing more welcoming than a door opening for you.','neep-2024-12-english-1-section-1') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
