INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('neep-2024-12-english-1-section-1-sentence-2-3','neep-2024-12-english-1',1,2,'Particularly useful in busy locations or during times of emergency, the doors act as crowd management by reducing the obstacles put in peoples’ way.','neep-2024-12-english-1-section-1') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('neep-2024-12-english-1-section-1-sentence-3-1','neep-2024-12-english-1',2,0,'As well as making access both in and out of buildings easier for people, the difference in the way many of these doors open helps reduce the total area occupied by them.','neep-2024-12-english-1-section-1') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
