INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('neep-2024-12-english-1-section-5-sentence-2-3','neep-2024-12-english-1',401,2,'Environmental Protection Agency (EPA) far less authority to regulate wetlands and waterways.','neep-2024-12-english-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('neep-2024-12-english-1-section-5-sentence-2-4','neep-2024-12-english-1',401,3,'Specifically, a 5-4 majority decided that wetlands protected by the EPA under its Clean Water Act authority must have a “continuous surface connection” to bodies of water.','neep-2024-12-english-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('neep-2024-12-english-1-section-5-sentence-2-5','neep-2024-12-english-1',401,4,'This narrowing of the regulatory scope was a victory for builders, mining operators and other commercial interests often at odds with environmental rules.','neep-2024-12-english-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
