INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('neep-2024-12-english-2-section-1-sentence-3-5','neep-2024-12-english-2',2,4,'There are groups aimed at new parents, at those who want to try a new sport for the first time, or networking events for those in the same profession to meet up and share ideas.','neep-2024-12-english-2-section-1') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('neep-2024-12-english-2-section-1-sentence-4-1','neep-2024-12-english-2',3,0,'On the other hand, it’s also possible to have too much of a social life.','neep-2024-12-english-2-section-1') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('neep-2024-12-english-2-section-1-sentence-4-2','neep-2024-12-english-2',3,1,'If you feel like you’re always doing something and there is never any space in your calendar for downtime, you could suffer social burnout or social fatigue.','neep-2024-12-english-2-section-1') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
