INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('neep-2024-12-english-2-section-6-q-44','neep-2024-12-english-2-section-6',3,'choice','44. Mayghin Levine','[{"key":"A","text":"Students who stand out in a specific extracurricular activity will be favored by top-tier institutions."},{"key":"B","text":"Students whose extracurricular activity has benefited their community are likely to win a scholarship."},{"key":"C","text":"Undertaking too many extracurricular activities will hardly be seen as a plus by colleges."},{"key":"D","text":"A student who exhibits abilities in doing business can impress colleges."},{"key":"E","text":"High school students participating in a popular activity should excel in it."},{"key":"F","text":"Engaging in uncommon activities can demonstrate students’ determination and dedication."},{"key":"G","text":"It is advisable for students to choose an extracurricular activity that is related to their future study at college."}]','G','依据原文整理的参考答案，非官方答案。Mayghin Levine 认为活动与拟学专业相关是一大优势，对应 G。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
