INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('neep-2025-12-english-1-section-8','neep-2025-12-english-1',7,'writing','小作文','Section III · Writing · Part A · 10 points','["Read the following email from your classmate Paul and write him a reply.","Dear Li Ming,","I was really excited to hear that you’d invite some young craftsmen to demonstrate their innovative craft-making on campus. May I know more about what they’ll Show?","Also, I’d like to help with your preparation work. Please let me know what I can do.","Yours, Paul","Write your answer in about 100 words on the ANSWER SHEET.","Do not use your own name in your email; use “Li Ming” instead. (10 points)"]','["Read the following email from your classmate Paul and write him a reply.","Dear Li Ming,","I was really excited to hear that you’d invite some young craftsmen to demonstrate their innovative craft-making on campus. May I know more about what they’ll Show?","Also, I’d like to help with your preparation work. Please let me know what I can do.","Yours, Paul","Write your answer in about 100 words on the ANSWER SHEET.","Do not use your own name in your email; use “Li Ming” instead. (10 points)"]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
